@pytest.mark.asyncio
@pytest.mark.parametrize('cardinality, method_cls, method_arg', [
    (Cardinality.UNARY_UNARY, UnaryUnaryMethod, Empty()),
    (Cardinality.STREAM_UNARY, StreamUnaryMethod, [Empty()]),
])
async def test_unary_reply_error(cardinality, method_cls, method_arg):
    class Service:
        async def Case(self, stream):
            await stream.send_initial_metadata()
            await stream.send_trailing_metadata(status=Status.PERMISSION_DENIED)

        def __mapping__(self):
            return {
                '/test.Test/Case': Handler(
                    self.Case,
                    cardinality,
                    Empty,
                    Empty,
                )
            }

    async with ChannelFor([Service()]) as channel:
        method = method_cls(channel, '/test.Test/Case', Empty, Empty)
        with pytest.raises(GRPCError) as err:
            await method(method_arg)
        assert err.value.status is Status.PERMISSION_DENIED

@pytest.mark.asyncio
@pytest.mark.parametrize('cardinality, method_cls, method_res', [
    (Cardinality.STREAM_UNARY, StreamUnaryMethod, Empty()),
    (Cardinality.STREAM_STREAM, StreamStreamMethod, [Empty()]),
])
async def test_empty_streaming_request(cardinality, method_cls, method_res):
    class Service:
        async def Case(self, stream):
            await stream.send_message(Empty())

        def __mapping__(self):
            return {
                '/test.Test/Case': Handler(
                    self.Case,
                    cardinality,
                    Empty,
                    Empty,
                )
            }

    async with ChannelFor([Service()]) as channel:
        method = method_cls(channel, '/test.Test/Case', Empty, Empty)
        assert await method([]) == method_res

@pytest.mark.asyncio
async def test_send_custom_metadata(stream, stub):
    async with stream:
        await stream.send_initial_metadata(metadata={
            'foo': 'foo-value',
        })
        await stream.send_message(DummyReply(value='pong'))
        await stream.send_trailing_metadata(metadata={
            'bar': 'bar-value',
        })
    assert stub.__events__ == [
        SendHeaders(
            [
                (':status', '200'),
                ('content-type', 'application/grpc+proto'),
                ('foo', 'foo-value'),
            ],
            end_stream=False,
        ),
        SendData(
            encode_message(DummyReply(value='pong')),
            end_stream=False,
        ),
        SendHeaders(
            [
                ('grpc-status', str(Status.OK.value)),
                ('bar', 'bar-value'),
            ],
            end_stream=True,

@pytest.mark.asyncio
async def test_rpc_call():
    ctx = ClientServer(PingServiceHandler, PingServiceStub, codec=JSONCodec())
    async with ctx as (handler, stub):
        reply = await stub.UnaryUnary({'value': 'ping'})
        assert reply == {'value': 'pong'}

def test_custom_default():
    @dataclass
    class Config:
        param: Optional[int] = field(
            default=_DEFAULT,
            metadata={
                'my-default': 42,
            },
        )

    cfg = Config()
    assert cfg.param is _DEFAULT

    cfg_with_defaults = _with_defaults(cfg, 'my-default')
    assert cfg_with_defaults.param == 42

def test_default_none():
    @dataclass
    class Config:
        param: Optional[int] = field(
            default=_DEFAULT,
            metadata={
                'my-default': None,
            },
        )

    cfg = Config()
    assert cfg.param is _DEFAULT

    cfg_with_defaults = _with_defaults(cfg, 'my-default')
    assert cfg_with_defaults.param is None

def test_validate():
    @dataclass
    class Config:
        foo: Optional[float] = field(
            default=None,
            metadata={
                'validate': _optional(_chain(_of_type(int, float), _positive)),
            },
        )

        def __post_init__(self):
            _validate(self)

    assert Config().foo is None
    assert Config(foo=0.123).foo == 0.123
    assert Config(foo=42).foo == 42

    with pytest.raises(ValueError, match='"foo" should be positive'):
        assert Config(foo=0)

    with pytest.raises(TypeError, match='"foo" should be of type'):
        assert Config(foo='a')

def test_change_default():
    # all params should be optional
    @dataclass
    class Config:
        foo: Optional[float] = field(
            default=cast(None, _DEFAULT),
            metadata={
                'validate': _optional(_chain(_of_type(int, float), _positive)),
                'test-default': 1234,
            },
        )

        def __post_init__(self):
            _validate(self)

    assert _with_defaults(Config(foo=1), 'test-default').foo == 1

def test_const_imports():
    const = importlib.import_module('grpclib.const')
    assert getattr(const, 'Cardinality')
    assert getattr(const, 'Handler')

